// Using DiscoveryClient programmatically
@Service
@RequiredArgsConstructor
public class ServiceLocator {

    private final DiscoveryClient discoveryClient;

    public URI getServiceUri(String serviceName) {
        List<ServiceInstance> instances = discoveryClient.getInstances(serviceName);
        if (instances.isEmpty()) {
            throw new ServiceUnavailableException(serviceName);
        }
        // Client-side load balancing (round-robin)
        ServiceInstance instance = instances.get(
            ThreadLocalRandom.current().nextInt(instances.size()));
        return instance.getUri();
    }
}

@FeignClient(
    name = "payment-service",
    fallbackFactory = PaymentClientFallbackFactory.class,
    configuration = PaymentClientConfig.class
)
public interface PaymentClient {

    @PostMapping("/api/v1/payments")
    PaymentResponse processPayment(@RequestBody PaymentRequest request);

    @GetMapping("/api/v1/payments/{paymentId}")
    PaymentResponse getPayment(@PathVariable UUID paymentId);

    @GetMapping("/api/v1/payments")
    Page<PaymentResponse> listPayments(
        @RequestParam("customerId") UUID customerId,
        @RequestParam("page") int page,
        @RequestParam("size") int size);
}

@Component
@Slf4j
public class PaymentClientFallbackFactory implements FallbackFactory<PaymentClient> {

    @Override
    public PaymentClient create(Throwable cause) {
        return new PaymentClient() {
            @Override
            public PaymentResponse processPayment(PaymentRequest request) {
                log.error("Payment service unavailable, queuing for retry", cause);
                throw new ServiceDegradedException("Payment processing delayed", cause);
            }

            @Override
            public PaymentResponse getPayment(UUID paymentId) {
                log.warn("Payment service unavailable, returning cached response", cause);
                return PaymentResponse.unavailable(paymentId);
            }

            @Override
            public Page<PaymentResponse> listPayments(UUID customerId, int page, int size) {
                return Page.empty();
            }
        };
    }
}

public class PaymentClientConfig {

    @Bean
    public RequestInterceptor authInterceptor(OAuth2AuthorizedClientManager clientManager) {
        return template -> {
            OAuth2AuthorizedClient client = clientManager.authorize(
                OAuth2AuthorizeRequest.withClientRegistrationId("payment-service")
                    .principal("order-service")
                    .build());
            template.header("Authorization",
                "Bearer " + client.getAccessToken().getTokenValue());
        };
    }
}

@Configuration
public class GatewayConfig {

    @Bean
    public RouteLocator customRouteLocator(RouteLocatorBuilder builder) {
        return builder.routes()
            .route("order-service", r -> r
                .path("/api/v1/orders/**")
                .filters(f -> f
                    .stripPrefix(0)
                    .addRequestHeader("X-Gateway-Source", "api-gateway")
                    .retry(config -> config
                        .setRetries(3)
                        .setStatuses(HttpStatus.SERVICE_UNAVAILABLE)
                        .setBackoff(Duration.ofMillis(100), Duration.ofSeconds(2), 2, true))
                    .circuitBreaker(config -> config
                        .setName("orderServiceCB")
                        .setFallbackUri("forward:/fallback/orders"))
                    .requestRateLimiter(config -> config
                        .setRateLimiter(redisRateLimiter())
                        .setKeyResolver(userKeyResolver())))
                .uri("lb://order-service"))
            .route("payment-service", r -> r
                .path("/api/v1/payments/**")
                .filters(f -> f
                    .tokenRelay()
                    .circuitBreaker(config -> config
                        .setName("paymentServiceCB")
                        .setFallbackUri("forward:/fallback/payments")))
                .uri("lb://payment-service"))
            .build();
    }

    @Bean
    public RedisRateLimiter redisRateLimiter() {
        return new RedisRateLimiter(10, 20, 1); // 10 req/s, burst 20
    }

    @Bean
    public KeyResolver userKeyResolver() {
        return exchange -> Mono.justOrEmpty(
            exchange.getRequest().getHeaders().getFirst("X-User-Id"))
            .defaultIfEmpty("anonymous");
    }
}

@Service
@RequiredArgsConstructor
public class InventoryService {

    private final InventoryClient inventoryClient;
    private final CircuitBreakerRegistry circuitBreakerRegistry;

    @CircuitBreaker(name = "inventory", fallbackMethod = "getStockFallback")
    @Retry(name = "inventory", fallbackMethod = "getStockFallback")
    @Bulkhead(name = "inventory", type = Bulkhead.Type.THREADPOOL)
    public StockResponse getStock(String productId) {
        return inventoryClient.checkStock(productId);
    }

    private StockResponse getStockFallback(String productId, Throwable t) {
        log.warn("Inventory service unavailable for product {}: {}", productId, t.getMessage());
        return StockResponse.unknown(productId);
    }
}

